using System;
using UnityEngine;

namespace NeonBrawl
{
    /// <summary>Ground tiles (T sheet, 4 tiles in reading order) and props (P sheet) of one map look.</summary>
    [Serializable]
    public sealed class MapTheme
    {
        public Sprite[] Tiles = new Sprite[0];
        public Sprite[] Props = new Sprite[0];
    }

    /// <summary>
    /// Sprites sliced from the AI art sheets (generated by Neon Brawl ▸ Art ▸ Slice Art Sources).
    /// Arrays are in sheet reading order; <see cref="ArtIds"/> names the slots the game uses.
    /// Any empty slot falls back to the code-generated placeholder art.
    /// </summary>
    [CreateAssetMenu(menuName = "Neon Brawl/Art Catalog", fileName = "ArtCatalog")]
    public sealed class ArtCatalog : ScriptableObject
    {
        [Header("C1 · bodies (pivot = neck). Tint layer takes the outfit color, detail layer keeps its colors.")]
        public Sprite[] BodyTint = new Sprite[0];
        public Sprite[] BodyDetail = new Sprite[0];
        [Tooltip("Distance from the neck pivot to the gloves, in units (where the gun is held).")]
        public float HandsForward = 0.55f;

        [Header("C2 · heads (pivot = head center). Index 0 = bald head, 1.. = headgear.")]
        public Sprite[] Heads = new Sprite[0];

        [Header("C3 · hair styles (drawn like headgear) and back items")]
        public Sprite[] Hair = new Sprite[0];
        public Sprite[] Back = new Sprite[0];

        [Header("W1 / W2 · guns (side view, muzzle right)")]
        public Sprite[] GunsA = new Sprite[0];
        public Sprite[] GunsB = new Sprite[0];

        [Header("W3 · pickups")]
        public Sprite[] PickupIcons = new Sprite[0];
        public Sprite PickupHealth;
        public Sprite PickupAmmo;
        public Sprite PickupArmor;
        public Sprite PickupGrenade;
        public Sprite Coin;
        public Sprite Gem;

        [Header("FX1 glows · FX2 smoke & magic · FX3 blood, holes, debris")]
        public Sprite[] Fx1 = new Sprite[0];
        public Sprite[] Fx2 = new Sprite[0];
        public Sprite[] Fx3 = new Sprite[0];

        [Header("E0 shared props · T/P map themes (index 0 = T1/P1 … 4 = T5/P5)")]
        public Sprite[] Shared = new Sprite[0];
        public MapTheme[] Themes = new MapTheme[0];

        [Header("UI kit · U1 panels, U2 icons, U3 HUD, U4 rewards")]
        public Sprite Logo;
        public Sprite[] Panels = new Sprite[0];
        public Sprite[] Icons = new Sprite[0];
        public Sprite[] Hud = new Sprite[0];
        public Sprite[] Rewards = new Sprite[0];
        public Sprite LobbyArt;
        public Sprite LoadingArt;
        public Sprite AppIcon;

        public static readonly string[] BodyNames = { "T-SHIRT", "PLATE CARRIER", "HOODIE", "HEAVY ARMOR", "BOMBER", "GHILLIE", "MEDIC", "COMMANDO" };
        public static readonly string[] HeadNames =
        {
            "NONE", "COMBAT HELMET", "NIGHT VISION", "BERET", "CAP", "BANDANA", "COWBOY HAT", "BEANIE",
            "HOOD", "NINJA WRAP", "GAS MASK", "CROWN", "VIKING", "SAMURAI", "PILOT", "PIRATE"
        };
        public static readonly string[] HairNames = { "BROWN CUT", "BLACK MOP", "BLONDE", "SILVER", "BUZZ", "VIKING BRAID", "MESSY", "AFRO" };
        public static readonly string[] BackNames = { "JUNGLE PACK", "URBAN PACK", "DESERT PACK", "DRAGON WING" };

        public bool HasCharacters => BodyTint != null && BodyTint.Length > 0 && Heads != null && Heads.Length > 0;

        public static ArtCatalog Load() => Resources.Load<ArtCatalog>("ArtCatalog");

        /// <summary>Safe array lookup: null when the slot doesn't exist.</summary>
        public static Sprite At(Sprite[] a, int i) => a != null && i >= 0 && i < a.Length ? a[i] : null;

        public MapTheme Theme(int i) => Themes != null && i >= 0 && i < Themes.Length ? Themes[i] : null;
        public Sprite Panel(int i) => At(Panels, i);
        public Sprite Icon(int i) => At(Icons, i);
        public Sprite HudPart(int i) => At(Hud, i);
        public Sprite Reward(int i) => At(Rewards, i);
    }

    /// <summary>Names for the catalog slots (reading order on each sheet; checked against Builds/art_sheets).</summary>
    public static class ArtIds
    {
        // U1 panels / buttons
        public const int PanelBlue = 0, PanelGold = 1, PanelDark = 2, PanelTan = 3, PanelWood = 4, PanelDark2 = 5,
            PanelOrange = 6, PanelWood2 = 7, PanelSand = 8, PanelSlate = 9, PanelSteel = 10, PanelBeige = 11;

        // U2 icons
        public const int IconPlay = 0, IconPause = 1, IconGear = 2, IconHome = 3, IconCart = 4, IconHome2 = 5, IconShirt = 6,
            IconCartRed = 7, IconTrophy = 8, IconMedal = 9, IconHeart = 10, IconStar = 11, IconShield = 12, IconStar2 = 13,
            IconStar3 = 14, IconPerson = 15, IconFlagRed = 16, IconFlagBlue = 17, IconBadge = 18, IconRank = 19;

        // U4 rewards
        public const int RewardCoin = 0, RewardSilver = 1, RewardGem = 2, RewardRuby = 3, RewardChest = 4, RewardChest2 = 5,
            RewardChest3 = 6, RewardChestIron = 7, RankStar = 8, RankBlue = 9, RankRed = 10, RankGold = 11;

        // U3 HUD parts (-1 = not found on the sheet, code-drawn fallback) — set from Builds/art_sheets/U3.png
        public const int HudJoyBase = 16, HudJoyKnob = 17, HudAimRing = 11, HudFire = 5, HudKnife = 7, HudPlusGold = 13, HudPlusWhite = 14, HudPlusBlue = 15;

        // W3 pickups
        public const int PickGrenadeGreen = 0, PickGrenadeRed = 1, PickGrenadeBlue = 2, PickBottle = 3, PickMedkit = 4, PickAmmo = 5,
            PickCoin = 6, PickGem = 7, PickHeart = 8, PickShield = 9, PickMagnet = 10, PickBolt = 11;

        // FX1 glows
        public const int FlashOrange = 0, FlashBlue = 1, FlashGreen = 2, BoltBlue = 3, BoltPurple = 4, FlashCrescent = 5,
            RingBlue = 6, StarOrange = 7, StarPurple = 8;

        // FX2 smoke & magic
        public const int SmokeGrey = 0, SparkBurst = 1, Portal = 2, FireBurst = 3, FlameBlue = 4, StarViolet = 5,
            SmokeGrey2 = 6, SwirlBlue = 7, MagicPink = 8;

        // FX3 groups (blood splats, bullet holes, scorch craters, debris chunks) — set from Builds/art_sheets/FX3.png
        public static readonly int[] Fx3Blood = { 0, 1, 2, 3 };
        public static readonly int[] Fx3Holes = { 4, 5, 7, 8, 9, 10 };
        public static readonly int[] Fx3Scorch = { 6, 12, 13 };
        public static readonly int[] Fx3Smoke = { 11, 14 };
        public static readonly int[] Fx3Debris = { 15 };

        // E0 shared props
        public const int SharedCrate = 0, SharedBarrelRed = 1, SharedBarrelBlue = 2, SharedBarrelGrey = 3, SharedCrate2 = 4,
            SharedCrate3 = 5, SharedSandbags = 6, SharedTire = 7, SharedBarrier = 8, SharedBollard = 9, SharedCone = 10;
    }
}
